      3:  [{name:"Использование заклинаний", desc:"Заклинания волшебника. 2 заговора (доп. заговор на 10 ур.); заменяются при получении уровня воина. Изначально подготавливаете 3 заклинания 1 ур., список растёт с уровнем воина. Интеллект — заклинательная характеристика, фокусировкой может служить магическая фокусировка."},{name:"Военная связь", desc:"Ритуал (1 час, можно в короткий отдых) создаёт связь с оружием: вас нельзя обезоружить, пока вы не недееспособны, а бонусным действием можно призвать привязанное оружие в руку (на одном плане). До двух привязанных оружий одновременно."}],
      7:  [{name:"Боевая магия", desc:"Выполняя действие Атака, можно заменить одну атаку применением заговора волшебника со временем накладывания действие."}],
      10: [{name:"Мистический удар", desc:"Попав атакой оружием по существу, оно получает помеху на следующий спасбросок против вашего заклинания, наложенного до конца вашего следующего хода."}],
      15: [{name:"Волшебный рывок", desc:"Используя Всплеск действий, можно телепортироваться до 30 фт в видимое свободное пространство — до или после дополнительного действия."}],
      18: [{name:"Улучшенная боевая магия", desc:"Выполняя действие Атака, можно заменить две атаки применением заклинания волшебника 1 или 2 ур. со временем накладывания действие."}]
