      6:  [{name:"Целостность тела", desc:"Бонусным действием бросить кость боевых искусств и восстановить ХП = результат + мод.Мудрости (мин. 1). Число раз = мод.Мудрости (мин. 1), восстанавливается после долгого отдыха."}],
      11: [{name:"Быстрый шаг", desc:"После любого бонусного действия, кроме Поступи ветра, можно сразу использовать Поступь ветра."}],
      17: [{name:"Дрожащая ладонь", desc:"Попав безоружным ударом, за 4 очка духа запускаете вибрации в цели на число дней = уровень монаха; остановка вызывает спасбросок Телосложения — провал даёт 10к12 урона силовым полем, успех — половину. Одновременно действует только на одну цель."}]
