    window.FIGHTING_STYLES_2024 = FIGHTING_STYLES_2024;
    window.WEAPON_MASTERY_2024 = WEAPON_MASTERY_2024;
    window.CLASS_SKILL_OPTIONS_2024 = CLASS_SKILL_OPTIONS_2024;
